-- Metal Stack Ledger: starting data
-- Run once in the SQL Editor after 1_schema.sql.
-- Daily prices for Jan 1 - Oct 21, 2026 (palladium to Oct 16), USD per troy ounce.
-- Gold and silver: exchange-rates.org. Platinum and palladium: bullion-rates.com.

on conflict (metal, bucket) do nothing;

-- Starting spot prices (Oct 22, 2026, about 8:20 PM Central). The updater overwrites these on its first run.
on conflict (metal) do update set price = excluded.price, quoted_at = excluded.quoted_at, source = excluded.source, updated_at = now();
